import { Box, Flex, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import { Icon } from "../../../Icon";
import { ClockFive } from "../../../Icon/icons";
import { type ConversationEvent, type ConversationEventAction } from "../../../types";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";

interface BotTurnEndedEventProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
}

export const BotTurnEndedEvent = forwardRef<HTMLDivElement | null, BotTurnEndedEventProps>(
  (props: BotTurnEndedEventProps, ref) => {
    const { event, isSelected = false, conversationEventActions, ...otherProps } = props;
    const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
    const [isHovered, setIsHovered] = React.useState(false);

    return (
      <Flex
        css={hoverableContainerSx}
        ref={ref}
        tabIndex={0}
        role="button"
        position="relative"
        cursor="pointer"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        {...otherProps}
      >
        {isHovered && (
          <ConversationEventActionButton event={event} actions={conversationEventActions} />
        )}
        <Box css={baseMessageSx}>
          <Icon icon={ClockFive} style={iconSx} />
          <Text textStyle="xs" variant="muted" lineClamp={2} wordBreak="break-all">
            Agent turn ended
          </Text>
        </Box>
      </Flex>
    );
  },
);

BotTurnEndedEvent.displayName = "BotTurnEndedEvent";
